function vhpScale(scale, v) {
  if (!isFinite(v)) return "";
  if (v <= scale[0][0]) return `rgb(${scale[0].slice(1).join(",")})`;
  for (let k = 1; k < scale.length; k++) {
    if (v <= scale[k][0]) {
      const [a, ...ca] = scale[k - 1], [b, ...cb] = scale[k];
      const f = (v - a) / (b - a);
      return `rgb(${ca.map((x, j) => Math.round(x + (cb[j] - x) * f)).join(",")})`;
    }
  }
  return `rgb(${scale[scale.length - 1].slice(1).join(",")})`;
}

/* ------------------------------------------------------------- thermo */
class VhpThermo {
  constructor(d) {
    this.d = d;
    this.sat = d.sat;
  }
  static interp(xs, ys, x) {
    const n = xs.length;
    if (!isFinite(x)) return NaN;
    if (xs[0] < xs[n - 1]) {
      if (x <= xs[0]) return ys[0] + ((ys[1] - ys[0]) * (x - xs[0])) / (xs[1] - xs[0]);
      if (x >= xs[n - 1]) return ys[n - 2] + ((ys[n - 1] - ys[n - 2]) * (x - xs[n - 2])) / (xs[n - 1] - xs[n - 2]);
      let lo = 0, hi = n - 1;
      while (hi - lo > 1) {
        const m = (lo + hi) >> 1;
        if (xs[m] <= x) lo = m; else hi = m;
      }
      return ys[lo] + ((ys[hi] - ys[lo]) * (x - xs[lo])) / (xs[hi] - xs[lo]);
    }
    return NaN;
  }
  col(i) {
    return this.sat.map((r) => r[i]);
  }
  tDew(p) {
    return VhpThermo.interp(this.col(2), this.col(0), p);
  }
  tBub(p) {
    return VhpThermo.interp(this.col(1), this.col(0), p);
  }
  pDew(T) {
    return VhpThermo.interp(this.col(0), this.col(2), T);
  }
  pBub(T) {
    return VhpThermo.interp(this.col(0), this.col(1), T);
  }
  hLiq(T) {
    return VhpThermo.interp(this.col(0), this.col(3), T);
  }
  hSatVap(T) {
    return VhpThermo.interp(this.col(0), this.col(4), T);
  }
  /* Superheated vapour enthalpy at pressure p (bar a) and temperature T (°C). */
  hVap(p, T) {
    const ts = this.tDew(p);
    let sh = T - ts;
    if (!isFinite(sh)) return NaN;
    if (sh < 0) sh = 0;
    const tg = this.d.tg, shg = this.d.sh, vap = this.d.vap;
    const row = (i) => VhpThermo.interp(shg, vap[i], sh);
    const xs = tg, ys = tg.map((_, i) => row(i));
    return VhpThermo.interp(xs, ys, ts);
  }
}

